{
  "steps": [
    {
      "id": 1,
      "claim": "Emulators are software that replicate console hardware and do not contain copyrighted game code.",
      "evidence": "Court rulings such as Sony Corp. v. Connectix (2000) held that clean‑room implementations of emulators are lawful.",
      "weight": 0.12,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Nintendo's classic games (the ROM code) are protected by copyright.",
      "evidence": "U.S. Copyright Act protects original computer code for the life of the author plus 70 years; Nintendo's titles were released after 1978 and remain under copyright.",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "Distributing or downloading a ROM without Nintendo’s permission infringes the exclusive reproduction and distribution rights of the copyright holder.",
      "evidence": "17 U.S.C. §106 gives the owner the exclusive right to reproduce and distribute the work; unauthorized copying is a violation.",
      "weight": 0.18,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "The first‑sale doctrine does not permit making a digital copy (ROM) of a game you own physically.",
      "evidence": "First‑sale allows resale of the physical medium but does not extend to reproducing the copyrighted code; courts have treated ROM dumping as a separate right.",
      "weight": 0.12,
      "depends_on": [2]
    },
    {
      "id": 5,
      "claim": "The legality of creating a personal backup ROM from a cartridge you own is uncertain and cannot be relied upon as a general exemption.",
      "evidence": "The DMCA prohibits circumvention of technological protection measures, and fair‑use analysis is fact‑specific; no clear statutory right exists for making a ROM backup.",
      "weight": 0.15,
      "depends_on": [4]
    },
    {
      "id": 6,
      "claim": "Because no reliable legal exemption exists for copying ROMs, obtaining classic Nintendo ROMs from the internet without Nintendo’s permission is illegal.",
      "evidence": "Combines steps 3‑5: without a valid exception, downloading or sharing ROMs violates copyright law.",
      "weight": 0.23,
      "depends_on": [3,5]
    }
  ],
  "answer": "No",
  "confidence": 0.88,
  "considered": [
    {
      "answer": "Yes",
      "reason_rejected": "A 'Yes' would require a universally accepted legal exception for personal backups or public‑domain status, which does not exist; the prevailing legal view treats unauthorized ROM downloads as infringement."
    }
  ]
}
